$sql .= ", (SELECT COUNT(*) AS total FROM " . DB_PREFIX . "order_product op LEFT JOIN `" . DB_PREFIX . "order` o ON (op.order_id = o.order_id) WHERE op.product_id = p.product_id) AS total_order";
/* NeoSeo Product Labels - end */

		/* NeoSeo Product Labels - begin */
		if(isset($data['filter_label_id']) && $data['filter_label_id'] >= 0){
            $query = $this->db->query("SELECT * FROM " . DB_PREFIX . "labels WHERE label_id='" . (int) $data['filter_label_id'] . "'");
            $ids = array();
            if ($query->num_rows){
                $now = date('Y-m-d H:i') . ':00';
                    if ($query->row['type'] == "1") {
                    // Новинки
                    $limit = $query->row['product_limit'];
                    $newdate = date('Y-m-d', strtotime('-' . $query->row['days'] . ' day'));
                    $products = $this->db->query("SELECT p.product_id FROM " . DB_PREFIX . "product p LEFT JOIN " . DB_PREFIX . "product_to_store p2s ON (p.product_id = p2s.product_id) WHERE p.date_added >= '" . $newdate . "' AND p.date_available <= '" . $now . "' AND p2s.store_id = '" . (int) $this->config->get('config_store_id') . "' limit ".$limit);
                    foreach ($products->rows as $row) {
                        $ids[$row['product_id']] = $row['product_id'];
                    }
                    $sort_label = $ids ? "p.sort_order ASC, p.product_id IN (".implode(',',$ids).")" : '';
                } else if ($query->row['type'] == "2") {
                    // Популярные
                    $limit = $query->row['product_limit'];
                    $viewes = $query->row['viewes'];
                    $products = $this->db->query("SELECT p.product_id FROM " . DB_PREFIX . "product p LEFT JOIN " . DB_PREFIX . "product_to_store p2s ON (p.product_id = p2s.product_id) WHERE p.status = '1' AND p.date_available <= '" . $now . "' AND p2s.store_id = '" . (int) $this->config->get('config_store_id') . "' AND p.viewed >= '" . (int)$viewes . "' ORDER BY p.viewed, p.date_added DESC LIMIT " . (int) $limit);
                    foreach ($products->rows as $row) {
                        $ids[] = $row['product_id'];
                    }
                    $sort_label = $ids ? "p.sort_order ASC, p.product_id IN (".implode(',',$ids).")" : '';
                } else if ($query->row['type'] == "3") {
                    // Хиты продаж
                    $limit = $query->row['product_limit'];
                    $sold = $query->row['sold'];
                    $products = $this->db->query("SELECT op.product_id, COUNT(*) AS total FROM " . DB_PREFIX . "order_product op LEFT JOIN `" . DB_PREFIX . "order` o ON (op.order_id = o.order_id) LEFT JOIN `" . DB_PREFIX . "product` p ON (op.product_id = p.product_id) LEFT JOIN " . DB_PREFIX . "product_to_store p2s ON (p.product_id = p2s.product_id) WHERE o.order_status_id > '0' AND p.status = '1' AND p.date_available <= '" . $now . "' AND p2s.store_id = '" . (int) $this->config->get('config_store_id') . "' GROUP BY op.product_id HAVING(total) >= " . (int)$sold . " ORDER BY total DESC LIMIT " . (int) $limit);
                    foreach ($products->rows as $row) {
                        $ids[] = $row['product_id'];
                    }
                    $sort_label = $ids ? "p.sort_order ASC, p.product_id IN (".implode(',',$ids).")" : '';
                }else if ($query->row['type'] == "4") {
                    // Нет на складе
                    $limit = $query->row['product_limit'];
                    $products = $this->db->query("SELECT p.product_id FROM " . DB_PREFIX . "product p LEFT JOIN " . DB_PREFIX . "product_to_store p2s ON (p.product_id = p2s.product_id) WHERE p.status = '1' AND p.date_available <= '" . $this->NOW . "' AND p2s.store_id = '" . (int) $this->config->get('config_store_id') . "' AND p.quantity < '1' LIMIT " . (int) $limit);
                    $ids = array();
                    foreach ($products->rows as $row) {
                        $ids[] = $row['product_id'];
                    }
                    $sort_label = $ids ? "p.sort_order ASC, p.product_id IN (".implode(',',$ids).")" : '';
                } else if ($query->row['type'] == "5") {
                    // В наличии
                    $limit = $query->row['product_limit'];
                    $products = $this->db->query("SELECT p.product_id FROM " . DB_PREFIX . "product p LEFT JOIN " . DB_PREFIX . "product_to_store p2s ON (p.product_id = p2s.product_id) WHERE p.status = '1' AND p.date_available <= '" . $this->NOW . "' AND p2s.store_id = '" . (int) $this->config->get('config_store_id') . "' AND p.quantity > '0' LIMIT " . (int) $limit);
                    $ids = array();
                    foreach ($products->rows as $row) {
                        $ids[] = $row['product_id'];
                    }
                    $sort_label = $ids ? "p.sort_order ASC, p.product_id IN (".implode(',',$ids).")" : '';
                }else {
                        $products = $this->db->query("SELECT product_id FROM " . DB_PREFIX . "product_to_labels WHERE label_id =".$data['filter_label_id']);
                        $ids = array();
                        foreach ($products->rows as $row) {
                            $ids[] = $row['product_id'];
                        }
                        $sort_label = $ids ? "p.sort_order ASC, p.product_id IN (".implode(',',$ids).")" : '';
                }
            } else {
                $product_to_labels = $this->db->query("SELECT product_id FROM " . DB_PREFIX . "product_special WHERE customer_group_id = '" . $this->config->get('config_customer_group_id') . "' GROUP BY product_id");

                foreach ($product_to_labels->rows as $row) {
                    $ids[] = $row['product_id'];
                }
                $sort_label = $ids ? "p.sort_order ASC, p.product_id IN (".implode(',',$ids).")" : '';
            }
        }
		/* NeoSeo Product Labels - end */

