$list_labels = $this->model_tool_neoseo_product_labels->getListLabels();

$languages=$this->model_localisation_language->getLanguages();
$system_languages=$languages[$this->config->get('config_language')]['language_id'];
$data['product_labels'] = array();
foreach ($list_labels as $label){
        $array_name =  unserialize($label['name']);
        $label['name']=$array_name[$system_languages];
        $products = $this->model_tool_neoseo_product_labels->getLabelProducts($label["label_id"]);
        if($products){
                $label['products']=$products;
        }
        $data['product_labels'][] = $label;
}
if (isset($this->request->get['product_id'])) {
    $data['product_id']=$this->request->get['product_id'];
}
